          "condition": {
            "mode": "glide_scripted_query",
            "value": "(function execute(table) {\n  \n      \n      var options = [];\n  \n      var grNI = new GlideRecord(table);\n      grNI.addQuery('request_type',vaInputs.request_type.getValue());\n      grNI.addQuery('requested_for',vaInputs.user);\n      grNI.orderBy('short_description');\n      grNI.orderBy('priority');\n      grNI.query();\n  \n            \n      while(grNI.next()) {\n          options.push({ 'value': grNI.getUniqueValue(), 'label': grNI.getValue('number') + \" (\" + grNI.getDisplayValue('priority') + \"): \" + grNI.getValue('short_description') });\n      }\n  \n      // Return the array\n      return options;\n  \n  })(table)"
          },
